// 3. The cubit subscribes and refreshes itself - behavior stays in the cubit.
NotificationsCubit({this.repo = const NotificationsRepo()})
    : super(const NotificationsState()) {
  _listenForNewNotifications();
  loadNotifications();
}

void _listenForNewNotifications() {
  _pushSubscription = PushEventBus.instance.stream.listen(
    (Map<String, dynamic> _) => unawaited(_load(silent: true)),
  );
  _resumeSubscription = AppLifecycleService.instance.onResumed.listen(
    (void _) => unawaited(_load(silent: true)),
  );
}

@override
Future<void> close() async {
  await _pushSubscription?.cancel();
  await _resumeSubscription?.cancel();
  return super.close();
}

Future<void> _load({bool silent = false}) async {
  if (_isFetching) return; // no duplicate request when push races pull-to-refresh
  _isFetching = true;
  try {
    final List<NotificationModel> notifications =
        await repo.fetchNotifications();
    if (isClosed) return;
    emit(state.copyWith(
      status: NotificationsStatus.success,
      notifications: _keepPendingReads(notifications),
      clearError: true,
    ));
  } on AppException catch (error) {
    _emitLoadFailure(error.key, silent);
  } catch (error) {
    _emitLoadFailure(ErrorMapper.map(error), silent);
  } finally {
    _isFetching = false;
  }
}

// A refresh nobody asked for must not replace content or raise a toast.
void _emitLoadFailure(String errorKey, bool silent) {
  if (isClosed) return;
  if (silent && state.notifications.isNotEmpty) return;
  emit(state.copyWith(
      status: NotificationsStatus.failure, errorKey: errorKey));
}

// An in-flight markRead POST must survive a refresh landing mid-flight.
List<NotificationModel> _keepPendingReads(List<NotificationModel> items) {
  if (_pendingReads.isEmpty) return items;
  return items
      .map((NotificationModel item) =>
          _pendingReads.contains(item.id) ? item.withRead(true) : item)
      .toList(growable: false);
}

