// error_mapper.dart — the only authority on whether a session survives.
class ErrorMapper {
  /// The codes that say the session is finished, whatever the request was.
  /// The account's own state is deliberately never consulted: states are an
  /// administrative list that grows without the app being rebuilt, and a
  /// state this build has not heard of would read as "fine, carry on".
  static const Set<int> sessionEndedCodes = <int>{401, 403};

  /// One notice for every code above, so a new state needs no new wording.
  static const String sessionEndedKey = 'session_expired';

  static bool endsSession(int? statusCode) =>
      statusCode != null && sessionEndedCodes.contains(statusCode);

  static bool sessionIsOver(Object error) => toException(error).endsSession;

  /// An envelope that failed on a 2xx transport has its reason in the body,
  /// so that code carries the same weight as the transport one.
  static int? _failingCode(int? transportCode, int envelopeCode) {
    if (transportCode != null && transportCode >= 300) return transportCode;
    if (envelopeCode == ApiEnvelope.successCode) return transportCode;
    return envelopeCode;
  }

  static String _mapStatusCode(int? statusCode) {
    if (endsSession(statusCode)) return sessionEndedKey;
    return switch (statusCode) { /* 400, 404, 422, 429, 5xx ... */ };
  }
}

// AppException carries the verdict so nothing downstream re-judges a code.
class AppException implements Exception {
  const AppException(this.key, {/* ... */ this.endsSession = false});
  final bool endsSession;
}

// SessionGuard acts on it, in one place.
static Future<void> endIfRefused(AppException error) async {
  if (!error.endsSession) return;
  if (!DeviceSessionService.hasSession) return; // a refused login is not a sign-out
  await forceSignOut(noticeKey: ErrorMapper.sessionEndedKey);
}

// Both arrival paths are covered, because this API also answers 200 with
// its own code in the envelope:
//   auth_interceptor.onError  -> transport refusals (401 keeps its refresh first)
//   ApiClient._send catch     -> envelope refusals that never reach a Dio interceptor

