// The transform can only be measured once the SVG has decoded, and
// flutter_svg decodes off the main isolate - which needs real elapsed time,
// hence runAsync rather than pumping fake durations alone.
Future<void> settle() async {
  for (var i = 0; i < 4; i++) {
    await tester.runAsync(
      () => Future<void>.delayed(const Duration(milliseconds: 50)),
    );
    await tester.pump(const Duration(milliseconds: 100));
  }
  expect(tester.takeException(), isNull);
}

