  // SvgPicture subtree, under VectorGraphic > FittedBox > SizedBox.
  final flipped = tester
      .widgetList<Transform>(
        find.descendant(
          of: find.byType(AppSvg),
          matching: find.byType(Transform),
        ),
      )
      .where((widget) => widget.transform.getRow(0).x < 0);

  expect(
    flipped.isNotEmpty,
    value == TextDirection.rtl,
    reason: value == TextDirection.rtl
        ? 'the glyph must be mirrored under RTL so it points right'
        : 'the glyph must be drawn as authored under LTR, pointing left',
  );
}

