// Resolve the fallback in the initializer list. Another initializing formal
// is in scope there as a parameter, so `identifier` can be read while the
// field of the same name is still being built.
class OtpArgs {
  const OtpArgs({
    required this.identifier,
    required this.purpose,
    AuthIdentifier? sentTo,
  }) : sentTo = sentTo ?? identifier;

  final AuthIdentifier identifier;
  final OtpPurpose purpose;
  final AuthIdentifier sentTo; // non-null, defaulted, no getter needed
}

// Where the fallback is read at build time rather than fixed at
// construction, keep the field nullable and use `this.`:
class AppSkeletonTileRow extends StatelessWidget {
  const AppSkeletonTileRow({
    required this.leading,
    this.gap = 10,
    this.trailingGap, // `this.` — the field initializes itself
  });

  final double gap;
  final double? trailingGap;

  @override
  Widget build(BuildContext context) =>
      SizedBox(width: (trailingGap ?? gap).w);
}

